// Makes worker-vectors.json with the dashboard's own code (modules/edge-agents/sign.ts), so the Go tests check the
// agent against exactly what the Worker does. The key is made here and thrown away. Run from the repo root:
//   node agent/testdata/gen-worker-vectors.mjs > agent/testdata/worker-vectors.json
import { canonicalJson, commandKey, commandString, fingerprint, signCommand } from "../../modules/edge-agents/sign.ts";
import { b64urlEncode } from "../../packages/core/src/util.ts";

const seed = Buffer.from(crypto.getRandomValues(new Uint8Array(32))).toString("base64");
const { priv, pub } = await commandKey(seed);

// args as the Worker hands them out: JSON.parse of what it stored
const argsList = [
  {},
  { delay_s: 30 },
  { target: "gaming-pc" },
  { b: 1, a: { d: [2, { y: 1, x: 2 }], c: null }, e: true, f: false },
  { n: [1.5, -0, 1e21, 1e-7, 123456789012345, 0.1] },
  { s: 'quote " back \\ nl \n tab \t ctl \u0001 \u001f html <>& ls   ps   é 😀' },
  { "é": 1, "z": 2, "a": 3, "😀": 4, "￿": 5, "B": 6 },
];
const commands = [];
for (const [i, a] of argsList.entries()) {
  const args = JSON.parse(JSON.stringify(a));
  const c = { agent: "ag_gaming-pc", id: `cmd_test${i}`, op: i === 1 ? "pc.shutdown" : "agent.ping", args, expires: 1794236700000 + i };
  commands.push({
    ...c,
    wire: JSON.stringify({ id: c.id, op: c.op, args, tier: "safe", expires: c.expires }),
    canonical: canonicalJson(args),
    string: await commandString(c),
    sig: await signCommand(priv, c),
  });
}
const raw = new Uint8Array(32).map((_, i) => i + 1);
console.log(JSON.stringify({
  note: "generated by gen-worker-vectors.mjs from modules/edge-agents/sign.ts; the signing key was thrown away",
  command_key: pub,
  commands,
  fingerprint: { pubkey: b64urlEncode(raw), fingerprint: await fingerprint(b64urlEncode(raw)) },
}, null, 2));
